INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('purification-of-the-heart', 'episode', NULL, 'Ostentation', 0, 6, 'Ostentation', '', NULL, NULL, NULL, NULL, 'purification of the heart ostentation', 'ostentation', '');
